mapper.select:
SELECT COUNT(*)
FROM chat_session
WHERE create_time >= #{startTime}
  AND create_time < #{endTime}

SELECT COUNT(*)
FROM chat_message
WHERE create_time >= #{startTime}
  AND create_time < #{endTime}

SELECT COUNT(*)
FROM chat_session
WHERE agent_id = #{agentId}
  AND status = 'CLOSED'
  AND end_time >= #{startTime}
  AND end_time < #{endTime}

SELECT user.id AS agent_id, user.username, COUNT(session.id) AS active_session_count FROM sys_user user LEFT JOIN chat_session session ON session.agent_id = user.id AND session.status = 'ACTIVE' WHERE user.id IN
#{agentId}
GROUP BY user.id, user.username ORDER BY active_session_count ASC, user.id ASC

SELECT #{agentId} AS agent_id, COUNT(rating.session_id) AS rating_count, COALESCE(ROUND(AVG(rating.rating), 2), 0) AS average_rating, COALESCE(SUM(CASE WHEN rating.rating = 1 THEN 1 ELSE 0 END), 0) AS one_star_count, COALESCE(SUM(CASE WHEN rating.rating = 2 THEN 1 ELSE 0 END), 0) AS two_star_count, COALESCE(SUM(CASE WHEN rating.rating = 3 THEN 1 ELSE 0 END), 0) AS three_star_count, COALESCE(SUM(CASE WHEN rating.rating = 4 THEN 1 ELSE 0 END), 0) AS four_star_count, COALESCE(SUM(CASE WHEN rating.rating = 5 THEN 1 ELSE 0 END), 0) AS five_star_count FROM chat_session_rating rating JOIN chat_session session ON session.id = rating.session_id
AND session.agent_id = #{agentId}
AND rating.create_time >= #{fromTime}
AND rating.create_time < #{toTime}
